FRigUnit_TwoBoneIKSimplePerItem_Execute()
{
    DECLARE_SCOPE_HIERARCHICAL_COUNTER_RIGUNIT()
	URigHierarchy* Hierarchy = ExecuteContext.Hierarchy;
	if (Hierarchy == nullptr)
	{
		return;
	}

	if (!CachedItemAIndex.UpdateCache(ItemA, Hierarchy) ||
		!CachedItemBIndex.UpdateCache(ItemB, Hierarchy))
	{
		return;
	}

	CachedEffectorItemIndex.UpdateCache(EffectorItem, Hierarchy);
	CachedPoleVectorSpaceIndex.UpdateCache(PoleVectorSpace, Hierarchy);

	if (Weight <= SMALL_NUMBER)
	{
		return;
	}

	FVector PoleTarget = PoleVector;
	if (CachedPoleVectorSpaceIndex.IsValid())
	{
		const FTransform PoleVectorSpaceTransform = Hierarchy->GetGlobalTransform(CachedPoleVectorSpaceIndex);
		if (PoleVectorKind == EControlRigVectorKind::Direction)
		{
			PoleTarget = PoleVectorSpaceTransform.TransformVectorNoScale(PoleTarget);
		}
		else
		{
			PoleTarget = PoleVectorSpaceTransform.TransformPositionNoScale(PoleTarget);
		}
	}

	FTransform TransformA = Hierarchy->GetGlobalTransform(CachedItemAIndex);
	FTransform TransformB = TransformA;
	TransformB.SetLocation(Hierarchy->GetGlobalTransform(CachedItemBIndex).GetLocation());
	FTransform TransformC = Effector;

	float LengthA = ItemALength;
	float LengthB = ItemBLength;

	if (LengthA < SMALL_NUMBER)
	{
		FTransform InitialTransformA = Hierarchy->GetInitialGlobalTransform(CachedItemAIndex);
		FVector Scale = FVector::OneVector;
		if (InitialTransformA.GetScale3D().SizeSquared() > SMALL_NUMBER)
		{
			Scale = TransformA.GetScale3D() / InitialTransformA.GetScale3D();
		}
		FVector Diff = InitialTransformA.GetLocation() - Hierarchy->GetInitialGlobalTransform(CachedItemBIndex).GetLocation();
		Diff = Diff * Scale;
		LengthA = Diff.Size();
	}

	if (LengthB < SMALL_NUMBER && CachedEffectorItemIndex != INDEX_NONE)
	{
		FTransform InitialTransformB = Hierarchy->GetInitialGlobalTransform(CachedItemBIndex);
		FVector Scale = FVector::OneVector;
		if (InitialTransformB.GetScale3D().SizeSquared() > SMALL_NUMBER)
		{
			Scale = TransformB.GetScale3D() / InitialTransformB.GetScale3D();
		}
		FVector Diff = InitialTransformB.GetLocation() - Hierarchy->GetInitialGlobalTransform(CachedEffectorItemIndex).GetLocation();
		Diff = Diff * Scale;
		LengthB = Diff.Size();
	}

	if (LengthA < SMALL_NUMBER || LengthB < SMALL_NUMBER)
	{
		UE_CONTROLRIG_RIGUNIT_REPORT_WARNING(TEXT("Item Lengths are not provided.\nEither set item length(s) or set effector item."));
		return;
	}

	FControlRigMathLibrary::SolveBasicTwoBoneIK(TransformA, TransformB, TransformC, PoleTarget, PrimaryAxis, SecondaryAxis, SecondaryAxisWeight, LengthA, LengthB, bEnableStretch, StretchStartRatio, StretchMaximumRatio);

	if (ExecuteContext.GetDrawInterface() != nullptr && DebugSettings.bEnabled)
	{
		const FLinearColor Dark = FLinearColor(0.f, 0.2f, 1.f, 1.f);
		const FLinearColor Bright = FLinearColor(0.f, 1.f, 1.f, 1.f);
		ExecuteContext.GetDrawInterface()->DrawLine(DebugSettings.WorldOffset, TransformA.GetLocation(), TransformB.GetLocation(), Dark);
		ExecuteContext.GetDrawInterface()->DrawLine(DebugSettings.WorldOffset, TransformB.GetLocation(), TransformC.GetLocation(), Dark);
		ExecuteContext.GetDrawInterface()->DrawLine(DebugSettings.WorldOffset, TransformB.GetLocation(), PoleTarget, Bright);
		ExecuteContext.GetDrawInterface()->DrawBox(DebugSettings.WorldOffset, FTransform(FQuat::Identity, PoleTarget, FVector(1.f, 1.f, 1.f) * DebugSettings.Scale * 0.1f), Bright);
	}

	if (Weight < 1.0f - SMALL_NUMBER)
	{
		FVector PositionB = TransformA.InverseTransformPosition(TransformB.GetLocation());
		FVector PositionC = TransformB.InverseTransformPosition(TransformC.GetLocation());
		TransformA.SetRotation(FQuat::Slerp(Hierarchy->GetGlobalTransform(CachedItemAIndex).GetRotation(), TransformA.GetRotation(), Weight));
		TransformB.SetRotation(FQuat::Slerp(Hierarchy->GetGlobalTransform(CachedItemBIndex).GetRotation(), TransformB.GetRotation(), Weight));
		if(CachedEffectorItemIndex != INDEX_NONE)
		{
			TransformC.SetRotation(FQuat::Slerp(Hierarchy->GetGlobalTransform(CachedEffectorItemIndex).GetRotation(), TransformC.GetRotation(), Weight));
		}
		TransformB.SetLocation(TransformA.TransformPosition(PositionB));
		TransformC.SetLocation(TransformB.TransformPosition(PositionC));
	}

	Hierarchy->SetGlobalTransform(CachedItemAIndex, TransformA, bPropagateToChildren);
	Hierarchy->SetGlobalTransform(CachedItemBIndex, TransformB, bPropagateToChildren);
	if(CachedEffectorItemIndex != INDEX_NONE)
	{
		Hierarchy->SetGlobalTransform(CachedEffectorItemIndex, TransformC, bPropagateToChildren);
	}
}

void FControlRigMathLibrary::SolveBasicTwoBoneIK(FTransform& BoneA, FTransform& BoneB, FTransform& Effector, const FVector& PoleVector, const FVector& PrimaryAxis, const FVector& SecondaryAxis, float SecondaryAxisWeight, float BoneALength, float BoneBLength, bool bEnableStretch, float StretchStartRatio, float StretchMaxRatio)
{
	FVector RootPos = BoneA.GetLocation();
	FVector ElbowPos = BoneB.GetLocation();
	FVector EffectorPos = Effector.GetLocation();

	AnimationCore::SolveTwoBoneIK(RootPos, ElbowPos, EffectorPos, PoleVector, EffectorPos, ElbowPos, EffectorPos, BoneALength, BoneBLength, bEnableStretch, StretchStartRatio, StretchMaxRatio);

	BoneB.SetLocation(ElbowPos);
	Effector.SetLocation(EffectorPos);

	FVector Axis = BoneA.TransformVectorNoScale(PrimaryAxis);
	FVector Target1 = BoneB.GetLocation() - BoneA.GetLocation();
	bool bIsFullyExtended = false;

	FVector BoneBLocation = BoneB.GetLocation();
	if (!Target1.IsNearlyZero() && !Axis.IsNearlyZero())
	{
		Target1 = Target1.GetSafeNormal();

		// Compute if the elbow is placed in the segment between the root and the effector (the limb is completely extended)
		{
			FVector BaseDirection = (EffectorPos - RootPos).GetSafeNormal();
			if (FMath::Abs(FVector::DotProduct(BaseDirection, Target1) - 1.0f) < KINDA_SMALL_NUMBER)
			{
				bIsFullyExtended = true;
			}
		}

		FQuat Rotation1 = FQuat::FindBetweenNormals(Axis, Target1);
		BoneA.SetRotation((Rotation1 * BoneA.GetRotation()).GetNormalized());

		Axis = BoneA.TransformVectorNoScale(SecondaryAxis);

		if (SecondaryAxisWeight > SMALL_NUMBER)
		{
			FVector Target2 =  bIsFullyExtended ? PoleVector - RootPos : BoneBLocation - (Effector.GetLocation() + BoneA.GetLocation()) * 0.5f;
			if (!Target2.IsNearlyZero() && !Axis.IsNearlyZero())
			{
				Target2 = Target2 - FVector::DotProduct(Target2, Target1) * Target1;
				Target2 = Target2.GetSafeNormal();

				FQuat Rotation2 = FQuat::FindBetweenNormals(Axis, Target2);
				if (!FMath::IsNearlyEqual(SecondaryAxisWeight, 1.f))
				{
					FVector RotationAxis = Rotation2.GetRotationAxis();
					float RotationAngle = Rotation2.GetAngle();
					Rotation2 = FQuat(RotationAxis, RotationAngle * FMath::Clamp<float>(SecondaryAxisWeight, 0.f, 1.f));
				}
				BoneA.SetRotation((Rotation2 * BoneA.GetRotation()).GetNormalized());
			}
		}
	}

	Axis = BoneB.TransformVectorNoScale(PrimaryAxis);
	Target1 = Effector.GetLocation() - BoneBLocation;
	if (!Target1.IsNearlyZero() && !Axis.IsNearlyZero())
	{
		Target1 = Target1.GetSafeNormal();
		FQuat Rotation1 = FQuat::FindBetweenNormals(Axis, Target1);
		BoneB.SetRotation((Rotation1 * BoneB.GetRotation()).GetNormalized());

		if (SecondaryAxisWeight > SMALL_NUMBER)
		{
			Axis = BoneB.TransformVectorNoScale(SecondaryAxis);
			FVector Target2 = bIsFullyExtended ?  PoleVector - BoneBLocation : BoneBLocation - (Effector.GetLocation() + BoneA.GetLocation()) * 0.5f;
			if (!Target2.IsNearlyZero() && !Axis.IsNearlyZero())
			{
				Target2 = Target2 - FVector::DotProduct(Target2, Target1) * Target1;
				Target2 = Target2.GetSafeNormal();

				FQuat Rotation2 = FQuat::FindBetweenNormals(Axis, Target2);
				if (!FMath::IsNearlyEqual(SecondaryAxisWeight, 1.f))
				{
					FVector RotationAxis = Rotation2.GetRotationAxis();
					float RotationAngle = Rotation2.GetAngle();
					Rotation2 = FQuat(RotationAxis, RotationAngle * FMath::Clamp<float>(SecondaryAxisWeight, 0.f, 1.f));
				}
				BoneB.SetRotation((Rotation2 * BoneB.GetRotation()).GetNormalized());
			}
		}
	}
}

UE_FORCEINLINE_HINT TVector<T> TVector<T>::operator*(const TVector<T>& V) const
{
    return TVector<T>(X * V.X, Y * V.Y, Z * V.Z);
}

template<typename T>
UE_FORCEINLINE_HINT TVector<T> TVector<T>::operator/(const TVector<T>& V) const
{
    return TVector<T>(X / V.X, Y / V.Y, Z / V.Z);
}

template<typename T>

UE_FORCEINLINE_HINT T TVector<T>::Size() const
{
    return FMath::Sqrt(X*X + Y*Y + Z*Z);
}

template<typename T>
UE_FORCEINLINE_HINT T TVector<T>::Length() const
{
	return Size();
}

template<typename T>
UE_FORCEINLINE_HINT T TVector<T>::SizeSquared() const
{
    return X*X + Y*Y + Z*Z;
}

template<typename T>
UE_FORCEINLINE_HINT T TVector<T>::SquaredLength() const
{

    "FRigUnit_TwoBoneIKSimplePerItem::Execute",
    [
        a,
        b,
        end,
        effector,
        Vector(primary),
        Vector(secondary),
        F32(secondary_weight),
        Vector(pole),
        Name(pole_kind),
        pole_space,
        Bool(stretch),
        F32(stretch_start),
        F32(stretch_max),
        F32(weight),
        F32(length_a),
        F32(length_b),
        Bool(propagate),
        _debug,
        _cached_a,
        _cached_b,
        _cached_end,
        _cached_pole,
    ],
) => {
    let Some(a) = self.hierarchy.item_index(a)? else {
        return Ok(());
    };
    let Some(b) = self.hierarchy.item_index(b)? else {
        return Ok(());
    };
    let end = self.hierarchy.item_index(end)?;
    let pole_space = self.hierarchy.item_index(pole_space)?;
    if *weight <= 1e-8 {
        return Ok(());
    }
    let mut pole = *pole;
    if let Some(space) = pole_space {
        let transform = self.hierarchy.transform(space, RigSpace::Global, false)?;
        pole = transform.rotation * pole;
        if pole_kind != "Direction" {
            pole += transform.translation;
        }
    }
    let transform_a = self.hierarchy.transform(a, RigSpace::Global, false)?;
    let transform_b = self.hierarchy.transform(b, RigSpace::Global, false)?;
    let mut bones = [
        transform_a,
        RigTransform {
            translation: transform_b.translation,
            ..transform_a
        },
        RigTransform::from_value(effector)?,
    ];
    let mut lengths = [*length_a, *length_b];
    for (index, (parent, child)) in [(a, Some(b)), (b, end)].into_iter().enumerate() {
        if lengths[index] < self.geometry.minimum_length
            && let Some(child) = child
        {
            let initial = self.hierarchy.transform(parent, RigSpace::Global, true)?;
            let scale = if initial.scale.length_squared() > 1e-8_f32 as f64 {
                bones[index].scale / initial.scale
            } else {
                bevy::math::DVec3::ONE
            };
            let delta = initial.translation
                - self
                    .hierarchy
                    .transform(child, RigSpace::Global, true)?
                    .translation;
            lengths[index] = (delta * scale).length() as f32;
        }
    }
    if lengths
        .iter()
        .any(|&length| length < self.geometry.minimum_length)
    {
        return Ok(());
    }
    self.geometry.solve(
        &mut bones,
        pole,
        *primary,
        *secondary,
        *secondary_weight,
        lengths,
        *stretch,
        *stretch_start,
        *stretch_max,
    );
    if *weight < 1.0 {
        let joint = bones[0].inverse_transform_point(bones[1].translation);
        let effector = bones[1].inverse_transform_point(bones[2].translation);
        bones[0].rotation =
            rig_slerp(transform_a.rotation, bones[0].rotation, *weight as f64);
        bones[1].rotation =
            rig_slerp(transform_b.rotation, bones[1].rotation, *weight as f64);
        if let Some(end) = end {
            let current = self.hierarchy.transform(end, RigSpace::Global, false)?;
            bones[2].rotation =
                rig_slerp(current.rotation, bones[2].rotation, *weight as f64);
        }
        bones[1].translation = bones[0].transform_point(joint);
        bones[2].translation = bones[1].transform_point(effector);
    }
    for (index, transform) in [Some(a), Some(b), end].into_iter().zip(bones) {
        if let Some(index) = index {
            self.hierarchy.set_transform(
                index,
                RigSpace::Global,
                false,
                transform,
                *propagate,
            )?;
        }
    }
}
